const CATEGORY_EMOJI = {
  'Nefes': '\ud83c\udf2c\ufe0f',
  'Beslenme': '\ud83c\udf7d\ufe0f',
  'Hareket': '\ud83d\udeb6',
  'Farkındalık': '\ud83e\udde0',
  'Gevşeme': '\ud83c\udf19',
  'Uyku': '\ud83d\ude34',
  'Vagus': '\ud83c\udfb5'
};

function turkeyNow() {
  // Turkiye UTC+3 sabit (DST yok). Epoch'a 3 saat ekleyip UTC getter'lariyla
  // okumak, Turkiye yerel saatini verir.
  return new Date(Date.now() + 3 * 60 * 60 * 1000);
}

function pad2(n) {
  return String(n).padStart(2, '0');
}

function trDateStr(d) {
  return d.getUTCFullYear() + '-' + pad2(d.getUTCMonth() + 1) + '-' + pad2(d.getUTCDate());
}

function findCurrentItem(dateStr, hour) {
  return SCHEDULE.find((it) => it.date === dateStr && it.hour === hour) || null;
}

function buildMessage(item) {
  const emoji = CATEGORY_EMOJI[item.category] || '\u23f0';
  const header = emoji + ' ' + pad2(item.hour) + ':00 \u2014 ' + item.title;
  const meta = item.duration ? item.category + ' \u00b7 ' + item.duration + ' dk' : item.category;
  return header + '\n' + meta + '\n\n' + item.detail;
}

async function sendTelegramMessage(env, text) {
  const url = 'https://api.telegram.org/bot' + env.TELEGRAM_BOT_TOKEN + '/sendMessage';
  const res = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ chat_id: env.TELEGRAM_CHAT_ID, text })
  });
  if (!res.ok) {
    const body = await res.text();
    throw new Error('Telegram API hatasi (' + res.status + '): ' + body);
  }
  return res.json();
}

async function runReminderCheck(env) {
  const nowTr = turkeyNow();
  const dateStr = trDateStr(nowTr);
  const hour = nowTr.getUTCHours();
  const item = findCurrentItem(dateStr, hour);
  if (!item) {
    return { matched: false, dateStr, hour };
  }
  await sendTelegramMessage(env, buildMessage(item));
  return { matched: true, dateStr, hour, title: item.title };
}

export default {
  async scheduled(event, env, ctx) {
    ctx.waitUntil(runReminderCheck(env));
  },

  async fetch(request, env) {
    const url = new URL(request.url);

    if (url.searchParams.get('test') === '1') {
      const nowTr = turkeyNow();
      await sendTelegramMessage(
        env,
        '\u2705 Test mesaj\u0131 \u2014 Cloudflare Worker ba\u011flant\u0131s\u0131 \u00e7al\u0131\u015f\u0131yor.\n' +
        '\u015eu an T\u00fcrkiye saatiyle: ' + trDateStr(nowTr) + ' ' + pad2(nowTr.getUTCHours()) + ':' + pad2(nowTr.getUTCMinutes())
      );
      return new Response('Test mesaji gonderildi. Telegram\'i kontrol et.');
    }

    // Parametresiz GET: gercek mesaj GONDERMEZ, sadece durumu raporlar
    // (yanlislikla tekrar mesaj gitmesin diye).
    const nowTr = turkeyNow();
    const dateStr = trDateStr(nowTr);
    const hour = nowTr.getUTCHours();
    const item = findCurrentItem(dateStr, hour);
    const report = {
      simdiTurkiyeSaati: dateStr + ' ' + pad2(hour) + ':' + pad2(nowTr.getUTCMinutes()),
      buSaateEsleyenMadde: item ? item.title : null,
      not: 'Gercek mesaj gondermek icin ?test=1 ekleyerek ziyaret et.'
    };
    return new Response(JSON.stringify(report, null, 2), { headers: { 'Content-Type': 'application/json' } });
  }
};
